import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch40Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final List<String> IDS=List.of("sm11_en_209","sm6_en_106","sm8_en_173","sm9_en_138","xy4_en_110");
    static final Set<String> VACUUMS=Set.of("swsh11_en_162","swsh11_en_217","swsh12-5_en_135");
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static TrainerProfile profile(String id){return NonPokemonBatch2Test.DATA.trainer(id).orElseThrow();}
    static CardInstance card(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static UUID bench(ServerMatch m,UUID p){return m.benchPokemonView(p).getFirst().pokemonId();}
    static void play(ServerMatch m){m.playTrainer(A,card(m,A,"trainer").instanceId(),null);}
    static void choose(ServerMatch m,int choice){var q=m.effectChoicePrompt(A);m.chooseEffectOption(A,q.resolutionId(),q.step(),choice);}
    static void select(ServerMatch m,List<UUID> cards){var q=m.effectCardPrompt(A);m.submitEffectCards(A,q.resolutionId(),q.step(),cards);}
    static void settle(ServerMatch m){NonPokemonBatch2Test.settle(m);}
    static CardInstance equip(ServerMatch m,UUID owner,String kind,UUID host){var c=card(m,owner,kind);if(kind.equals("tool"))m.attachToolByEffect(A,owner,EffectSourceZone.HAND,c.instanceId(),owner,host);else m.attachEnergyByEffect(A,owner,EffectSourceZone.HAND,c.instanceId(),owner,host);return c;}
    static ServerMatch game(String id){return GeneratedRuleBatch23Test.fixture(profile(id),0,EnergyType.DARKNESS);}
    static ServerMatch aiGame(String id){
        if(id.equals("sm11_en_209")){var m=NonPokemonBatch39Test.game(id,"Test",EnergyType.FIRE,Set.of(PokemonFamily.TAG_TEAM,PokemonFamily.GX),0);equip(m,A,"special",active(m,A));return m;}
        var m=game(id);equip(m,B,id.equals("sm6_en_106")?"special":"tool",active(m,B));return m;
    }
    public static void main(String[] args){tag();eneporter();xerosic();drill();faba();vacuum();System.out.println("NonPokemonBatch40Test passed: two physical double Energy transfers, opponent-only relocation and invalid-host discard, either-side Xerosic, exact Darkness cost, Faba owner/range/Lost Zone, Supporter protection and existing Lost Vacuum");}
    static void tag(){for(int amount:List.of(1,2)){
        var m=NonPokemonBatch39Test.game("sm11_en_209","Test",EnergyType.FIRE,Set.of(PokemonFamily.TAG_TEAM,PokemonFamily.GX),0);UUID from=active(m,A),to=bench(m,A);var one=equip(m,A,"special",from);var two=equip(m,A,"special",from);play(m);var p=m.effectPokemonPrompt(A);m.chooseEffectPokemon(A,p.resolutionId(),p.step(),from);var q=m.effectCardPrompt(A);check(q.maximum()==2&&q.candidates().containsAll(List.of(one,two)),"Tag Switch counted supplied units instead of cards");select(m,amount==2?List.of(one.instanceId(),two.instanceId()):List.of(one.instanceId()));var dest=m.effectAttachmentPrompt(A);check(dest.targets().equals(List.of(to)),"Tag Switch allowed source or opponent destination");m.chooseEffectAttachmentTarget(A,dest.resolutionId(),dest.step(),to);settle(m);check(m.activePokemonView(A).attachedEnergyIds().size()==2-amount&&m.benchPokemonView(A).getFirst().attachedEnergyIds().size()==amount&&!m.energyAttached(A),"Tag Switch lost cards or manual attachment");
    }var wrong=NonPokemonBatch39Test.game("sm11_en_209");equip(wrong,A,"special",active(wrong,A));check(!wrong.canPlayTrainer(A,card(wrong,A,"trainer").instanceId(),null),"Tag Switch allowed non-TAG TEAM source");}
    static void eneporter(){var m=game("sm6_en_106");var special=equip(m,B,"special",active(m,B));equip(m,B,"energy",active(m,B));equip(m,A,"special",active(m,A));play(m);check(m.effectCardPrompt(A).candidates().equals(List.of(special)),"Eneporter offered own or basic Energy");select(m,List.of(special.instanceId()));var q=m.effectAttachmentPrompt(A);check(q.targets().equals(List.of(bench(m,B))),"Eneporter destination left opponent field or allowed same Pokemon");m.chooseEffectAttachmentTarget(A,q.resolutionId(),q.step(),bench(m,B));settle(m);check(m.benchPokemonView(B).getFirst().attachedEnergyIds().contains(special.instanceId()),"Eneporter did not move intact physical card");
        var strong=NonPokemonBatch2Test.DATA.energyProfile("xy3_en_104").orElseThrow();var n=DynamicPassiveModifierTest.fixture(DynamicPassiveModifierTest.plainTool(),DynamicPassiveModifierTest.plainStadium(),strong,GeneratedRuleBatch8Test.hit(100,false),List.of(),0,profile("sm6_en_106"),Map.of("basic",EnergyType.FIGHTING,"evolved",EnergyType.PSYCHIC));n.endTurn(A);n.evolveByEffect(B,bench(n,B),card(n,B,"evolved").instanceId(),EvolutionPermission.CARD_EFFECT_ALL_TIMING);n.endTurn(B);var energy=equip(n,B,"special",active(n,B));n.playTrainer(A,card(n,A,"item").instanceId(),null);select(n,List.of(energy.instanceId()));var dest=n.effectAttachmentPrompt(A);check(dest.targets().contains(bench(n,B)),"Eneporter incorrectly rejected invalid Energy host");n.chooseEffectAttachmentTarget(A,dest.resolutionId(),dest.step(),bench(n,B));settle(n);check(n.benchPokemonView(B).getFirst().attachedEnergyIds().isEmpty()&&n.privateView(B).discard().contains(energy)&&!n.privateView(A).discard().contains(energy),"Strong Energy did not discard to actual owner after incompatible move");
    }
    static void xerosic(){for(UUID owner:List.of(A,B))for(String kind:List.of("tool","special")){
        var m=game("xy4_en_110");var c=equip(m,owner,kind,active(m,owner));equip(m,owner,"energy",active(m,owner));play(m);choose(m,kind.equals("tool")?0:owner.equals(A)?1:2);check(m.effectCardPrompt(A).candidates().equals(List.of(c)),"Xerosic selected wrong attachment kind");select(m,List.of(c.instanceId()));settle(m);check(m.privateView(owner).discard().contains(c)&&m.activePokemonView(owner).attachedEnergyIds().size()==1,"Xerosic wrong owner or discarded Basic Energy");
    }}
    static void drill(){for(int branch:List.of(0,1,2)){
        var m=game("sm9_en_138");check(!m.canPlayTrainer(A,card(m,A,"trainer").instanceId(),null),"Drill allowed cost-only play with no target");CardInstance target;
        if(branch==2){target=card(m,A,"stadium");m.playTrainer(A,target.instanceId(),null);}else target=equip(m,B,branch==0?"tool":"special",active(m,B));
        play(m);var q=m.effectCardPrompt(A);check(q.candidates().stream().allMatch(c->m.cardDefinition(c.definitionId()).category()==CardCategory.POKEMON&&m.cardDefinition(c.definitionId()).pokemonTypes().contains(EnergyType.DARKNESS)),"Drill allowed non-Darkness cost");var cost=q.candidates().getFirst();select(m,List.of(cost.instanceId()));choose(m,branch);if(branch!=2)select(m,List.of(target.instanceId()));settle(m);check(m.privateView(A).discard().contains(cost)&&m.privateView(branch==2?A:B).discard().contains(target),"Drill failed payment or selected removal");
    }var wrong=GeneratedRuleBatch23Test.fixture(profile("sm9_en_138"),0,EnergyType.GRASS);equip(wrong,B,"tool",active(wrong,B));check(!wrong.canPlayTrainer(A,card(wrong,A,"trainer").instanceId(),null),"Drill used a non-Darkness Pokemon as activation cost");}
    static void faba(){for(String kind:List.of("tool","special","stadium"))for(UUID stadiumOwner:List.of(A,B)){
        var m=game("sm8_en_173");var ownTool=equip(m,A,"tool",active(m,A));var ownEnergy=equip(m,A,"special",active(m,A));var otherTool=equip(m,B,"tool",active(m,B));var otherEnergy=equip(m,B,"special",active(m,B));var basic=equip(m,B,"energy",active(m,B));var stadium=card(m,stadiumOwner,"stadium");if(stadiumOwner.equals(B))m.endTurn(A);m.playTrainer(stadiumOwner,stadium.instanceId(),null);if(stadiumOwner.equals(B))m.endTurn(B);CardInstance chosen=kind.equals("tool")?otherTool:kind.equals("special")?otherEnergy:stadium;play(m);var q=m.effectCardPrompt(A);check(q.candidates().size()==3&&q.candidates().containsAll(List.of(otherTool,otherEnergy,stadium))&&!q.candidates().contains(ownTool)&&!q.candidates().contains(ownEnergy)&&!q.candidates().contains(basic),"Faba target range leaked own attachment or Basic Energy");select(m,List.of(chosen.instanceId()));settle(m);check(m.privateView(chosen.ownerId()).lostZone().contains(chosen)&&!m.privateView(chosen.ownerId()).discard().contains(chosen),"Faba did not send actual owner's card to Lost Zone");
    }var guard=NonPokemonBatch35Test.namedGame(profile("sm8_en_173"),"other","Espeon V",Set.of(PokemonFamily.V));var tool=equip(guard,B,"tool",active(guard,B));play(guard);select(guard,List.of(tool.instanceId()));settle(guard);check(guard.activePokemonView(B).attachedTools().contains(tool)&&guard.privateView(B).lostZone().isEmpty(),"Faba bypassed Moon & Sun Badge Supporter protection");}
    static void vacuum(){var m=game("swsh11_en_162");var tool=equip(m,A,"tool",active(m,A));equip(m,A,"special",active(m,A));play(m);var cost=m.effectCardPrompt(A).candidates().getFirst();select(m,List.of(cost.instanceId()));check(m.effectCardPrompt(A).candidates().equals(List.of(tool)),"Lost Vacuum gained Energy targets or lost own-Tool targeting");select(m,List.of(tool.instanceId()));settle(m);check(m.privateView(A).lostZone().containsAll(List.of(cost,tool)),"Lost Vacuum cost/removal regressed");}
}
